    'anyone': 'f6/f692bd3198c2985b.mp3',
    'anyone who has tried to translate poetry between distant languages will recognise the peculiar frustration of working with words that refuse to migrate. kurmancî, like many oral cultures, contains terms saturated with cultural weight that english simply does not possess. consider the word "bêrî" — roughly translated as "longing" or "homesickness," yet neither captures its full resonance for someone separated from their mountains. similarly, the german "heimat" or the portuguese "saudade" defy clean conversion. some translators argue we should naturalise these terms, finding the closest equivalent in the target language even at the cost of nuance. others insist that genuine cultural exchange requires us to keep certain words untranslated, allowing them to expand the receiving language\'s emotional vocabulary. i tend toward the second camp, though i recognise the practical difficulties. when my kurmancî novel was translated into english last year, my translator and i spent nearly a month debating how to handle the word "bêrî." we eventually decided to use the original term in italics, with a brief contextual note. reviews were mixed; some readers found the choice precious, others praised it. what surprised me most was a letter from a kurdish reader in toronto, who wrote that seeing "bêrî" preserved in an english text gave her unexpected dignity. sometimes the strangeness is the point': '17/1787ef374d0e437a.mp3',
