    'bye': '2c/2cbed220c04e51e9.mp3',
    'bêrîvan is fourteen, lives two doors down from us, and has somehow become one of the most respected voices in our neighbourhood. it started two years ago when she noticed that the small stream behind our houses was filling with plastic bottles. instead of complaining online, which is what most of us would have done, she organised a saturday clean-up with three classmates. six families joined that first weekend. by the end of the year, more than fifty people were participating monthly, including the local imam and two retired teachers. what strikes me about bêrîvan is not just her energy but her patience. she takes time to explain her concerns to elderly neighbours who are sceptical of "green talk" from the west. she speaks to them in kurmancî, connects environmental care to traditional respect for water and land, and never makes anyone feel ignorant. last month, the municipality finally installed proper bins along the stream after she presented data she had collected herself. her mother told me that bêrîvan dreams of studying environmental engineering one day. looking at what she has already accomplished, i have no doubt she will succeed': '73/73788035fc04122b.mp3',
