    'dear rojîn, i am writing this letter because some things are too important for a quick message. it has been two years since i moved to berlin for university, and people often ask whether i feel german now. the honest answer is more complicated than yes or no. i cook dolma on sundays exactly the way mother taught us, but i also queue politely for the u-bahn and apologise for things that are not my fault — both very german habits. my german friends find my kurdish hospitality overwhelming at first, while my visiting cousins from home cannot understand why nobody talks loudly on the train. i have stopped trying to choose between the two parts of myself. i think identity, for our generation, is less like a single house and more like a key chain: you carry several keys, and you use the right one when each door appears. write back soon and tell me how things are at home. with love, hêvî': 'f2/f2b92eb402b793b6.mp3',
