    'everlasting': 'f6/f67ecb203cb78d78.mp3',
    'every culture has its own traditional clothing, and for kurds, traditional dress carries deep meaning. my grandmother still wears her long colorful dress almost every day. she has kept this habit for her entire life. when i was younger, i did not fully understand why she refused modern clothes. now i see that her dress is more than fabric. each pattern tells a story about her region. young kurds today are rediscovering traditional clothes, especially during newroz. social media has helped, because people proudly share photos of their outfits. i believe that keeping our traditions alive does not mean rejecting the modern world. we can wear jeans on monday and kiras on sunday': '4d/4d66656a92cfc0e2.mp3',
    'every sunday at noon, i open a video call with my grandmother in sulaymaniyah. she cannot read or write english, and my kurmanci is still shaky, but that hour is the most important thirty minutes of my week. she shows me the herbs she is drying on the roof. i show her my university library. sometimes my little cousin baran joins, shouting words in three languages at once. when my grandmother forgets a word in kurdish, she uses arabic; when i forget, i slip into english, and we laugh. my mother says our family has always lived between languages, and i am beginning to understand that this is not a problem to fix but a small inheritance to carry': '14/14a7e01c6f983f6a.mp3',
    'every year at eid, our small flat in germany becomes a big kurdish house. my mother starts cooking two days before. the smell of rice, lamb and sweet dough fills every room. my father calls his brother in hewler on video so our cousins can see us. on the morning of eid, i wear new clothes. my grandmother gives me a small gift. my younger sister runs to the neighbours to share baklava. for one day, two languages, two countries and three generations sit at the same table': 'd6/d6fa4f02f1536694.mp3',
