    'i moved from my village to stenbol three years ago. at first, the city shocked me. the streets were always crowded and the noise never stopped. i missed the silence of my mountains deeply. however, as time passed, i learned to appreciate city life. there are libraries where i can study any subject and theaters where i have watched kurdish plays. i have made friends from different backgrounds. still, every summer i go back to my village. i think both places have shaped who i am. the village gave me roots, and the city gave me wings. i would not want to live without either one': 'fe/feead01f4b8eca08.mp3',
