    'in the garden stood a huge tree': '68/68663b64cc6991d2.mp3',
    'in the small coffeehouse of our town, an old man named apê reşo tells stories every evening. people call him a dengbêj. he has been performing for almost sixty years, yet his voice still carries the same strength. when he sings about lost lovers and ancient battles, even the noisy children become silent. my father took me there when i was eight, and i have attended his performances regularly since then. what amazes me is that he never uses paper. he has memorized hundreds of songs, each one thousands of lines long. recently, a university started recording his work to preserve it. i am glad they did. if we lose our dengbêjs, we lose a part of our memory that no book can truly replace': 'a5/a50345200410f913.mp3',
