    'lake': '27/279e0b028973dfd5.mp3',
    'lake van is one of the biggest lakes in the region. last summer, my family drove there for a picnic. the water was blue and clean. we sat under a large tree. my father grilled fish on the fire. i swam for a long time with my brothers. a small boat passed by us. we have been to many places, but this was special. we went home happy but very tired': '92/92281848a9c43e10.mp3',
    'lamp': '7d/7d79577654c5a269.mp3',
    'landlord': 'f6/f63faeb185edb2eb.mp3',
