    'landscape': 'b5/b58751eaabee6449.mp3',
    'language': '62/62a94267ef1c4af7.mp3',
    'language is far more than a communication tool. it is the living memory of a people, a bridge between generations, and often the clearest mirror of cultural identity. for many kurds, speaking kurmancî is not merely a linguistic choice but a political and emotional statement. my grandfather, who grew up in a period when speaking kurdish at school was forbidden, used to whisper lullabies to me in kurmancî at night. those whispers planted something in me that decades of schooling in another language could never uproot. linguists argue that when a language disappears, an entire worldview vanishes with it. i have come to believe this personally. each word in kurmancî carries centuries of mountains, rivers, migrations, and songs. when young kurds today debate whether to invest time in learning their mother tongue, i wish they understood that they are not just learning vocabulary. they are inheriting an ancient conversation between their ancestors and the land itself. losing that conversation would impoverish not only kurds but all of humanity': '53/53d9292679d684c6.mp3',
    'languorous': '45/45d7a176c53389f6.mp3',
    'laptop': 'f5/f52e0062a1d85c37.mp3',
    'last': 'f6/f6a96288d2db8c29.mp3',
    'last month i bought a new phone. i had saved money for six months. i wanted a phone with a good camera. in the shop, the seller showed me three models. i chose the blue one because it was the lightest. since i got it, i have taken many pictures of my city. i also talk to my cousin in germany every week. technology has made our lives easier': '65/65a13d7a0bf3f27a.mp3',
    'last summer, i visited amed with my family. we stayed there for five days. the old city has black stone walls. we walked on them and took many photos. i have never seen such beautiful walls before. we also ate traditional food in small restaurants. i bought a silk scarf for my grandmother. she was very happy when i gave it to her': '8b/8b77c9ffae479500.mp3',
    'last week': 'be/beeab74c3a184b0d.mp3',
    'last winter, i noticed that my younger cousins, although born to kurdish parents, hardly ever spoke kurmancî at home. they understood when adults addressed them, but they always replied in english. this worried me, not because i judged them, but because i knew what they were quietly losing. after thinking about it for weeks, i decided to start a weekly podcast in simple kurmancî, aimed specifically at heritage speakers like my cousins. i chose topics that interest teenagers: video games, music, sports, life advice. the response surprised me. within three months, the podcast had reached over five thousand listeners across europe and north america. many sent messages saying it was the first time they had heard kurmancî used to discuss their actual daily lives, rather than only weddings and proverbs. producing the show takes about ten hours a week, which is significant alongside my full-time job. yet whenever i feel tired, i remember a message from a fifteen-year-old in stockholm: "i never thought my grandmother\'s language could talk about my world too."': '27/27a4706a26ab284c.mp3',
