    'learn': 'e3/e3bd8831d9aa2f7a.mp3',
    'learned': '16/164a1ccd5c9d9b31.mp3',
    'learning a new language is not easy. you need patience and practice. but it opens many doors in life': '3b/3b9eff28d367b2ed.mp3',
    'learning english as a kurmancî speaker has been a fascinating journey for me. at first, i thought the grammar would be very difficult, but i soon realized that kurmancî and english share more than i expected. both languages use similar sentence structures in simple present tense. of course, pronunciation was another story. i had to practice english sounds for months before my friends could understand me clearly. what helped me most was watching movies with subtitles and reading children\'s books. if someone asks me for advice, i always say that consistency matters more than talent. you cannot learn a language in a week, but you can surely master it in a few years': '94/9454a4977950d739.mp3',
