    'my grandmother\'s kitchen is always warm. she has cooked traditional food there for fifty years. last week i visited her. she was making savar with yogurt. the smell was wonderful. she taught me how to shape the bulgur. i burned my hand a little, but she laughed and helped me. she has a small garden behind the kitchen. all her vegetables come from there. i love spending time with her': 'd0/d0c0a12c5ea5145d.mp3',
