    'my uncle plays the tembûr. he has played it since he was a child. the tembûr is a traditional kurdish instrument with a long neck. every friday evening, my uncle comes to our house. he sings old songs about love and mountains. my father claps along with him. i have learned two short songs from him. he says music keeps our culture alive. i want to play like him one day': '0d/0d55e09554235903.mp3',
