    'three years ago, i made what most people considered a strange decision. i left my well-paid job in london and moved back to my grandparents\' village in the mountains. friends warned me that i would lose touch with the modern world, but the pandemic had taught me something unexpected: meaningful work no longer requires a fixed office. with a decent internet connection and a laptop, i now design websites for clients in five different countries. each morning i drink çay watching the sunrise over the same valley where my grandfather used to herd sheep. there are challenges, of course. power cuts happen, fast deliveries are impossible, and some clients struggle to pronounce my village\'s name. yet i have gained something money cannot buy: a sense of being firmly rooted while still belonging to a wider world. i would not exchange this life for any city again': '25/2564f18917555349.mp3',
