    'two summers ago, i spent three weeks at my cousin\'s farm where there was no internet connection. at first, i felt lost. i kept reaching for my phone out of habit. by the third day, something strange happened. i started noticing details i had never seen before: the color of the sunrise, the sound of insects at night, the way my aunt\'s hands moved while she was making bread. i read two full novels in those weeks. i had long conversations with my cousins about our dreams and fears. when i returned to the city, i realized that constant connection had been stealing my attention for years. now i try to have one offline day every week. it has completely changed how i experience time': '67/67ebbe442de5888c.mp3',
    'two years ago': '3b/3bb23d32449e651c.mp3',
    'two years ago, i traveled by train for the first time. the journey was long but exciting. i sat next to a window and watched the villages pass by. i saw green fields and small rivers. an old man sat next to me. he told me stories about his youth. he had worked as a teacher for forty years. i have never forgotten his kind face. we shared bread and cheese during the trip': '86/8600aeb54dd9a423.mp3',
