    'when': 'd3/d3270411aebf8a04.mp3',
    'when berfîn opened her small workshop in mardin three years ago, she had no business plan worth mentioning. she had something arguably more valuable: she had spent the previous decade quietly learning the nearly extinct art of natural dye weaving from elderly women in scattered villages. these women, most of them in their seventies and eighties, had assumed their knowledge would die with them. none of their grown children, occupied with urban professions, had shown the slightest interest in inheriting techniques that took years to master and offered no obvious financial reward. berfîn changed that quietly, one visit at a time, recording everything from the precise season for harvesting madder roots to the particular wooden tools required for combing wool. today, her workshop employs eleven young women, most of whom would otherwise have migrated abroad for work. their carpets, woven with colours derived entirely from local plants, sell to design shops in berlin, tokyo, and brooklyn. what i find most striking about berfîn\'s success is not the commercial dimension, impressive though it is. it is the way she has reframed traditional craft, not as nostalgia for a vanished past, but as a viable contemporary livelihood that happens to honour ancestral knowledge. the elderly women who taught her now visit the workshop monthly, watching their techniques flourish in younger hands. one of them told me last summer that she had stopped fearing death. her knowledge would outlive her after all': 'bd/bd042d42fcc0b0a0.mp3',
    'when did they arrive': '00/00952a7b69ed27b0.mp3',
    'when i see her, i will tell her. (i will see her)': 'ab/abde70a098134915.mp3',
    'when i was nineteen, i started working at a small bookshop in the city. the owner, mr. azad, had run the shop for thirty years. i thought selling books would be easy, but i was wrong. during my first week, i could not find anything on the shelves. mr. azad had his own system which nobody could understand except him. slowly, i learned the places of different authors. more importantly, i learned how to listen to customers. some came looking for a specific book, while others just wanted to talk about literature. that job taught me that people value attention almost as much as the product itself. even now, after five years, i still visit the shop whenever i can': 'f3/f368b3e141861892.mp3',
